{"command":"cd /tmp/subs && python3 - <<'EOF'
import pickletools, io, glob

SKIP = {'MEMOIZE','FRAME','PROTO','LONG_BINPUT','BINPUT','PUT','EMPTY_DICT','MARK','SETITEMS','STOP','NEWTRUE','NEWFALSE','NONE'}

def scalars(path):
    ops = list(pickletools.genops(io.BytesIO(open(path,'rb').read())))
    seq=[]
    for op,arg,pos in ops:
        if op.name in SKIP: continue
        if op.name in ('SHORT_BINUNICODE','BINUNICODE','UNICODE'): seq.append(('s',arg))
        elif op.name in ('BINFLOAT','FLOAT'): seq.append(('f',arg))
        elif op.name in ('BININT','BININT1','BININT2','LONG1'): seq.append(('i',arg))
        elif op.name in ('STACK_GLOBAL','GLOBAL'): seq.append(('G',arg))
        elif op.name in ('REDUCE','BUILD','EMPTY_TUPLE','TUPLE1','TUPLE2','TUPLE3','TUPLE','BINGET','GET','SHORT_BINBYTES','BINBYTES','BINPERSID','DUP','POP','SETITEM','EMPTY_LIST','APPENDS','APPEND'): seq.append(('op',op.name))
        else: seq.append(('?',op.name))
    return seq

for f in sorted(glob.glob('model_*.pkl')):
    seq = scalars(f)
    # print only the header portion before first GLOBAL/OrderedDict stuff
    head=[]
    for kind,val in seq:
        head.append(f"{kind}:{val!r}")
    print('=====',f)
    print(' | '.join(head[:14]))
EOF"}
